/**
 * @suppress
 */
public object FfiConverterTypeSuggestStore: FfiConverter<SuggestStore, Long> {
    override fun lower(value: SuggestStore): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): SuggestStore {
        return SuggestStore(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): SuggestStore {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: SuggestStore) = 8UL

    override fun write(value: SuggestStore, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


