/**
 * A single geographic place.
 *
 * This corresponds to a single row in the main "geoname" table described in
 * the GeoNames documentation [1]. We exclude fields we don't need.
 *
 * [1]: https://download.geonames.org/export/dump/readme.txt
 */
data class Geoname (
    /**
     * The `geonameid` straight from the geoname table.
     */
    var `geonameId`: kotlin.Long
    , 
    /**
     * The geoname type. This is derived from `feature_class` and
     * `feature_code` as a more convenient representation of the type.
     */
    var `geonameType`: GeonameType
    , 
    /**
     * The place's primary name.
     */
    var `name`: kotlin.String
    , 
    /**
     * ISO-3166 two-letter uppercase country code, e.g., "US".
     */
    var `countryCode`: kotlin.String
    , 
    /**
     * Primary geoname category. Examples:
     *
     * "PCLI" - Independent political entity: country
     * "A" - Administrative division: state, province, borough, district, etc.
     * "P" - Populated place: city, village, etc.
     */
    var `featureClass`: kotlin.String
    , 
    /**
     * Secondary geoname category, depends on `feature_class`. Examples:
     *
     * "ADM1" - Administrative division 1
     * "PPL" - Populated place like a city
     */
    var `featureCode`: kotlin.String
    , 
    /**
     * Administrative divisions. This maps admin division levels (1-based) to
     * their corresponding codes. For example, Liverpool has two admin
     * divisions: "ENG" at level 1 and "H8" at level 2. They would be
     * represented in this map with entries `(1, "ENG")` and `(2, "H8")`.
     */
    var `adminDivisionCodes`: Map<kotlin.UByte, kotlin.String>
    , 
    /**
     * Population size.
     */
    var `population`: kotlin.ULong
    , 
    /**
     * Latitude in decimal degrees (as a string).
     */
    var `latitude`: kotlin.String
    , 
    /**
     * Longitude in decimal degrees (as a string).
     */
    var `longitude`: kotlin.String
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeGeoname: FfiConverterRustBuffer<Geoname> {
    override fun read(buf: ByteBuffer): Geoname {
        return Geoname(
            FfiConverterLong.read(buf),
            FfiConverterTypeGeonameType.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterMapUByteString.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
        )
    }

    override fun allocationSize(value: Geoname) = (
            FfiConverterLong.allocationSize(value.`geonameId`) +
            FfiConverterTypeGeonameType.allocationSize(value.`geonameType`) +
            FfiConverterString.allocationSize(value.`name`) +
            FfiConverterString.allocationSize(value.`countryCode`) +
            FfiConverterString.allocationSize(value.`featureClass`) +
            FfiConverterString.allocationSize(value.`featureCode`) +
            FfiConverterMapUByteString.allocationSize(value.`adminDivisionCodes`) +
            FfiConverterULong.allocationSize(value.`population`) +
            FfiConverterString.allocationSize(value.`latitude`) +
            FfiConverterString.allocationSize(value.`longitude`)
    )

    override fun write(value: Geoname, buf: ByteBuffer) {
            FfiConverterLong.write(value.`geonameId`, buf)
            FfiConverterTypeGeonameType.write(value.`geonameType`, buf)
            FfiConverterString.write(value.`name`, buf)
            FfiConverterString.write(value.`countryCode`, buf)
            FfiConverterString.write(value.`featureClass`, buf)
            FfiConverterString.write(value.`featureCode`, buf)
            FfiConverterMapUByteString.write(value.`adminDivisionCodes`, buf)
            FfiConverterULong.write(value.`population`, buf)
            FfiConverterString.write(value.`latitude`, buf)
            FfiConverterString.write(value.`longitude`, buf)
    }
}



