    NO_KEYWORD_EXPANSION,
    /**
     * Use FTS matching against the full keywords, joined together.
     */
    FTS_AGAINST_FULL_KEYWORDS,
    /**
     * Use FTS matching against the title field
     */
    FTS_AGAINST_TITLE;

    


    companion object
}


