/**
 * The error type for all Suggest component operations. These errors are
 * exposed to your application, which should handle them as needed.
 */
sealed class SuggestApiException: kotlin.Exception() {
    
    class Network(
        
        val `reason`: kotlin.String
        ) : SuggestApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The server requested a backoff after too many requests
     */
    class Backoff(
        
        val `seconds`: kotlin.ULong
        ) : SuggestApiException() {
        override val message
            get() = "seconds=${ `seconds` }"
    }
    
    /**
     * An operation was interrupted by calling `SuggestStore.interrupt()`
     */
    class Interrupted(
        ) : SuggestApiException() {
        override val message
            get() = ""
    }
    
    class Other(
        
        val `reason`: kotlin.String
        ) : SuggestApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SuggestApiException> {
        override fun lift(error_buf: RustBuffer.ByValue): SuggestApiException = FfiConverterTypeSuggestApiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSuggestApiError : FfiConverterRustBuffer<SuggestApiException> {
    override fun read(buf: ByteBuffer): SuggestApiException {
        

        return when(buf.getInt()) {
            1 -> SuggestApiException.Network(
                FfiConverterString.read(buf),
                )
            2 -> SuggestApiException.Backoff(
                FfiConverterULong.read(buf),
                )
            3 -> SuggestApiException.Interrupted()
            4 -> SuggestApiException.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SuggestApiException): ULong {
        return when(value) {
            is SuggestApiException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SuggestApiException.Backoff -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`seconds`)
            )
            is SuggestApiException.Interrupted -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SuggestApiException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: SuggestApiException, buf: ByteBuffer) {
        when(value) {
            is SuggestApiException.Network -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SuggestApiException.Backoff -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`seconds`, buf)
                Unit
            }
            is SuggestApiException.Interrupted -> {
                buf.putInt(3)
                Unit
            }
            is SuggestApiException.Other -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



