                FfiConverterString.write(value.`iconUrl`, buf)
                FfiConverterString.write(value.`description`, buf)
                FfiConverterOptionalString.write(value.`rating`, buf)
                FfiConverterLong.write(value.`numberOfRatings`, buf)
                FfiConverterString.write(value.`guid`, buf)
                FfiConverterDouble.write(value.`score`, buf)
                Unit
            }
            is Suggestion.Yelp -> {
                buf.putInt(4)
                FfiConverterString.write(value.`url`, buf)
                FfiConverterString.write(value.`title`, buf)
                FfiConverterOptionalByteArray.write(value.`icon`, buf)
                FfiConverterOptionalString.write(value.`iconMimetype`, buf)
                FfiConverterDouble.write(value.`score`, buf)
                FfiConverterBoolean.write(value.`hasLocationSign`, buf)
                FfiConverterBoolean.write(value.`subjectExactMatch`, buf)
                FfiConverterTypeYelpSubjectType.write(value.`subjectType`, buf)
                FfiConverterString.write(value.`locationParam`, buf)
                Unit
            }
            is Suggestion.Mdn -> {
                buf.putInt(5)
                FfiConverterString.write(value.`title`, buf)
                FfiConverterString.write(value.`url`, buf)
                FfiConverterString.write(value.`description`, buf)
                FfiConverterDouble.write(value.`score`, buf)
                Unit
            }
            is Suggestion.Weather -> {
                buf.putInt(6)
                FfiConverterOptionalTypeGeoname.write(value.`city`, buf)
                FfiConverterDouble.write(value.`score`, buf)
                Unit
            }
            is Suggestion.Dynamic -> {
                buf.putInt(7)
                FfiConverterString.write(value.`suggestionType`, buf)
                FfiConverterOptionalTypeJsonValue.write(value.`data`, buf)
                FfiConverterOptionalString.write(value.`dismissalKey`, buf)
                FfiConverterDouble.write(value.`score`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





