/**
 * @suppress
 */
public object FfiConverterMapUByteString: FfiConverterRustBuffer<Map<kotlin.UByte, kotlin.String>> {
    override fun read(buf: ByteBuffer): Map<kotlin.UByte, kotlin.String> {
        val len = buf.getInt()
        return buildMap<kotlin.UByte, kotlin.String>(len) {
            repeat(len) {
                val k = FfiConverterUByte.read(buf)
                val v = FfiConverterString.read(buf)
                this[k] = v
            }
        }
    }

    override fun allocationSize(value: Map<kotlin.UByte, kotlin.String>): ULong {
        val spaceForMapSize = 4UL
        val spaceForChildren = value.map { (k, v) ->
            FfiConverterUByte.allocationSize(k) +
            FfiConverterString.allocationSize(v)
        }.sum()
        return spaceForMapSize + spaceForChildren
    }

    override fun write(value: Map<kotlin.UByte, kotlin.String>, buf: ByteBuffer) {
        buf.putInt(value.size)
        // The parens on `(k, v)` here ensure we're calling the right method,
        // which is important for compatibility with older android devices.
        // Ref https://blog.danlew.net/2017/03/16/kotlin-puzzler-whose-line-is-it-anyways/
        value.forEach { (k, v) ->
            FfiConverterUByte.write(k, buf)
            FfiConverterString.write(v, buf)
        }
    }
}




